 fig,axes=plt.subplots(1,2,figsize=(10,4));x=np.array([v['omega'] for v in final]);means=np.array([v['difference']['estimate'] for v in final]);lo=np.array([v['difference']['ci95'][0] for v in final]);hi=np.array([v['difference']['ci95'][1] for v in final]);axes[0].errorbar(range(3),means,yerr=[means-lo,hi-means],fmt='o',capsize=5);axes[0].axhline(0,color='gray',ls=':');axes[0].set_xticks(range(3),[str(v) for v in x]);axes[0].set_xlabel('Population scale Omega');axes[0].set_ylabel('Prepared minus homogeneous G projection');axes[0].set_title('T=0.01: mean and approximate 95% interval');sd=np.array([v['control']['sd'] for v in final]);axes[1].plot(x,sd,'o-',label='Four-control SD estimate');axes[1].plot(x,sd[0]*np.sqrt(10/x),'k--',label='Square-root reference, anchored at 10');axes[1].set_xscale('log',base=4);axes[1].set_xticks(x,[str(v) for v in x]);axes[1].set_xlabel('Population scale Omega');axes[1].set_ylabel('SD of homogeneous G projection');axes[1].set_title('Descriptive noise estimate; n=4 each');axes[1].legend(fontsize=8);fig.tight_layout();fig.savefig(PUBLIC/'MG183_G_population_summary.png',dpi=160);plt.close(fig)
 with np.load(PUBLIC/'G_profiles_summary.npz') as z:
  fig,axes=plt.subplots(1,3,figsize=(12,3.7),sharex=True,sharey=True);center=int(np.argmin(ref[0]));relative=(np.arange(500)-center+250)%500-250;ix=np.where(abs(relative)<=40)[0];ix=ix[np.argsort(relative[ix])];template=ref[0]-ref[0].mean()
