  axes[0].set_ylabel('G concentration minus spatial mean');axes[0].legend(fontsize=7);fig.suptitle('T=0.01 prepared G profiles — descriptive bands, not a persistence test');fig.tight_layout();fig.savefig(PUBLIC/'MG183_G_profiles.png',dpi=160);plt.close(fig)
